// Red Alert 2 / Red Alert 3 unit "句子库" — the voice quotes from redalert.ts,
// enriched with Chinese translations so they become learnable English sentences
// (listen + translation). Includes the expansion packs Yuri's Revenge (merged
// into RA2) and Red Alert 3: Uprising (merged into RA3) so each main game's
// unit list stays comprehensive. This is a hand-curated bank feeding both the
// 红警 browse page and the 闯关 (challenge) system.
//
// NOTE: redalert.ts is auto-generated and must not be edited by hand. All
// hand-authored unit lines live here as a companion source.

export type RAGame = 'RA2' | 'RA3';

export interface RASentence {
  /** English line (verbatim / characteristic of the unit's voice clip). */
  en: string;
  /** Chinese translation. */
  zh: string;
  /** Unit name. */
  unit: string;
  /** Which game the unit belongs to. */
  game: RAGame;
  /** Action label, matching redalert.ts buckets (选中/移动/攻击/…). */
  group: string;
}

