export const RA_SENTENCES: RASentence[] = [...RA2_SENTENCES, ...RA3_SENTENCES];

/** Group sentences by unit (game-qualified id `game:unit`). */
export function raSentencesByUnit(): { id: string; unit: string; game: RAGame; sentences: RASentence[] }[] {
  const map = new Map<string, { id: string; unit: string; game: RAGame; sentences: RASentence[] }>();
  for (const s of RA_SENTENCES) {
    const id = `${s.game}:${s.unit}`;
    if (!map.has(id)) map.set(id, { id, unit: s.unit, game: s.game, sentences: [] });
    map.get(id)!.sentences.push(s);
  }
  const order: RAGame[] = ['RA2', 'RA3'];
  return [...map.values()].sort((a, b) => {
    const gi = order.indexOf(a.game) - order.indexOf(b.game);
    return gi !== 0 ? gi : a.unit.localeCompare(b.unit);
  });
}

export type RAUnitSentences = ReturnType<typeof raSentencesByUnit>[number];
  